/* Setlist AI MVP — local-first storage, transparent audio estimates, editable DJ set sequencing. */
const DB_NAME='setlist-ai-v1', STORE='tracks', PLAYLISTS='playlists';
let db, tracks=[], playlists=[], activeView='dashboard', activePlaylist=null, query='', genreFilter='all', moodFilter='all', toastTimer, catalogResults=[], catalogSearchText='', catalogBusy=false, catalogPage=0, catalogError='', youtubeApiKey=localStorage.getItem('setlist-youtube-api-key')||'';
const moods=['Feel-good','Celebratory','Chill','Romantic','Nostalgic','Euphoric','High-energy','Aggressive'];
const events=['Diwali party','Wedding','Sangeet','House party','Corporate party','Club night','College party','Sundowner'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const d=req.result;d.createObjectStore(STORE,{keyPath:'id'});d.createObjectStore(PLAYLISTS,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function all(store){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);});}
function put(store,item){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function remove(store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function uid(){return Math.random().toString(36).slice(2,9)+Date.now().toString(36)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function notify(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function prettyDuration(sec){if(!sec)return '—';return `${Math.floor(sec/60)}:${String(Math.floor(sec%60)).padStart(2,'0')}`}
function init(){if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});openDB().then(async d=>{db=d;tracks=await all(STORE);playlists=await all(PLAYLISTS);render();}).catch(()=>{document.body.innerHTML='<div style="padding:40px;color:white">This browser does not support local library storage. Please use a recent version of Safari, Chrome or Firefox.</div>';});
  document.addEventListener('click',handleClick);$('#audioInput').addEventListener('change',e=>importAudio([...e.target.files]));$('#csvInput').addEventListener('change',e=>importCSV(e.target.files[0]));$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#newSetBtn').onclick=()=>{activeView='builder';activePlaylist=null;render();};}
function handleClick(e){const nav=e.target.closest('[data-view]');if(nav){activeView=nav.dataset.view;activePlaylist=null;render();return;}const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action,id=action.dataset.id;
 if(a==='upload')$('#audioInput').click();if(a==='csv')$('#csvInput').click();if(a==='build'){activeView='builder';activePlaylist=null;render();}if(a==='generate')generatePlaylist();if(a==='open-playlist'){activePlaylist=id;activeView='builder';render();}if(a==='view-library'){activeView='library';render();}if(a==='view-settings'){activeView='settings';render();}if(a==='edit-track')editTrack(id);if(a==='delete-track')deleteTrack(id);if(a==='remove-playlist-track')removePlaylistTrack(id,Number(action.dataset.index));if(a==='export-csv')exportCSV();if(a==='save-playlist')savePlaylist();if(a==='save-youtube-key')saveYoutubeKey();if(a==='new-set'){activePlaylist=null;$('#prompt').value='';$('#setName').value='';}if(a==='dupes')showDuplicates();if(a==='reanalyze')reanalyzeMissing();if(a==='clear-library')clearLibrary();if(a==='delete-playlist')deletePlaylist(id);if(a==='discover-search')searchCatalogFromInput();if(a==='discover-genre'){$('#sourceQuery').value=action.dataset.query;searchCatalogFromInput();}if(a==='catalog-prev'){catalogPage=Math.max(0,catalogPage-1);render();}if(a==='catalog-next'){catalogPage=Math.min(Math.ceil(catalogResults.length/24)-1,catalogPage+1);render();}}
function render(){const root=$('#viewRoot');$('#navTrackCount').textContent=tracks.length;$$('.nav-link[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===activeView));$('#crumbTitle').textContent=activeView==='builder'?(activePlaylist?playlistById(activePlaylist)?.name||'Set builder':'Set builder'):{dashboard:'Overview',library:'My music',discover:'Discover',explore:'Mood explorer',settings:'Settings'}[activeView]||'Overview';renderSets();
 if(activeView==='dashboard')root.innerHTML=dashboardView();else if(activeView==='library')root.innerHTML=libraryView();else if(activeView==='builder')root.innerHTML=builderView();else if(activeView==='settings')root.innerHTML=settingsView();else if(activeView==='discover')root.innerHTML=discoverView();else root.innerHTML=soonView(activeView);
 if(activeView==='library'){const s=$('#search');if(s)s.oninput=()=>{query=s.value;renderLibraryRows();};const g=$('#genreFilter');if(g)g.onchange=()=>{genreFilter=g.value;renderLibraryRows();};const m=$('#moodFilter');if(m)m.onchange=()=>{moodFilter=m.value;renderLibraryRows();};renderLibraryRows();}if(activeView==='builder'&&activePlaylist)drawEnergyChart();}
function renderSets(){const n=$('#setNav');if(!playlists.length){n.innerHTML='<div class="empty-set-nav">Your first set starts here.</div>';return;}n.innerHTML=playlists.slice().sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,6).map(p=>`<button class="set-item" data-action="open-playlist" data-id="${p.id}"><span>${esc(p.name)}</span></button>`).join('');}
function dashboardView(){const totalMins=tracks.reduce((s,t)=>s+(t.duration||0),0)/60;const analyzed=tracks.filter(t=>t.bpm||t.key).length;const avg=tracks.length?Math.round(tracks.reduce((s,t)=>s+(+t.energy||0),0)/tracks.length):0;const topGenre=Object.entries(tracks.reduce((o,t)=>(o[t.genre||'Untagged']=(o[t.genre||'Untagged']||0)+1,o),{})).sort((a,b)=>b[1]-a[1])[0];return `<div class="page"><div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL DJ WORKSPACE</div><h1>Good evening, DJ.</h1><p class="page-sub">Your music, mapped and ready for the next great set.</p></div><div class="heading-actions"><button class="button" data-action="csv">⇧ Import CSV</button><button class="button button-primary" data-action="upload">＋ Add music</button></div></div>
 <section class="stat-grid"><div class="stat-card"><div class="stat-label">Tracks in your library</div><div class="stat-value">${tracks.length}</div><div class="stat-note stat-accent">${tracks.length?'READY TO MIX':'START HERE'}</div></div><div class="stat-card"><div class="stat-label">Analyzed tracks</div><div class="stat-value">${analyzed}</div><div class="stat-note">BPM + KEY</div></div><div class="stat-card"><div class="stat-label">Music in your crate</div><div class="stat-value">${Math.floor(totalMins/60)}<span style="font-size:14px;color:#8793a2">h ${Math.round(totalMins%60)}m</span></div><div class="stat-note">TOTAL PLAYTIME</div></div><div class="stat-card"><div class="stat-label">Average energy</div><div class="stat-value">${tracks.length?avg+'/10':'—'}</div><div class="stat-note">LIBRARY PULSE</div></div></section>
 <div class="content-grid"><div><section class="card hero-card"><div class="eyebrow">SET BUILDER · YOUR HEADLINER</div><h2>Turn a crate into a night to remember.</h2><p>Describe the room, the journey and the music. Setlist AI will shape a sequence from your own library.</p><button class="button button-primary" data-action="build">Build a DJ set <span>↗</span></button></section>
 <section class="card" style="margin-top:15px"><div class="card-header"><div><div class="card-title">Library at a glance</div><div class="card-kicker">A quick pulse check on your collection</div></div><button class="text-link" data-action="view-library">View music →</button></div><div class="feature-list"><div class="feature-chip"><b>${topGenre?esc(topGenre[0]):'No genres yet'}</b>${topGenre?`${topGenre[1]} tracks · your biggest crate`:'Import tracks or a CSV to start organizing.'}</div><div class="feature-chip"><b>${playlists.length} ${playlists.length===1?'set':'sets'} built</b>${playlists.length?'Your latest sequences are ready to revisit.':'Create a set for your next event.'}</div></div></section></div>
 <section class="card"><div class="card-header"><div><div class="card-title">Recently added</div><div class="card-kicker">Fresh tracks for your next session</div></div><span class="mono" style="font-size:9px">LOCAL</span></div>${tracks.length?`<div class="activity-list">${tracks.slice().sort((a,b)=>(b.addedAt||0)-(a.addedAt||0)).slice(0,5).map(t=>`<div class="activity-item"><div class="cover">♫</div><div style="min-width:0"><strong>${esc(t.title)}</strong><small>${esc(t.artist||'Unknown artist')} · ${esc(t.genre||'Untagged')}</small></div><span class="activity-time">${t.bpm?Math.round(t.bpm)+' BPM':'NEW'}</span></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">♫</div>Your crate is waiting.<br>Add music files or import a track list.</div><button class="button button-small" data-action="upload">＋ Add your first tracks</button>`}</section></div>
 <div class="notice">Analysis runs in your browser. BPM and energy are audio estimates; mood and event fit are editable, subjective labels.</div></div>`;}
function libraryView(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">YOUR COLLECTION</div><h1>My music</h1><p class="page-sub">One home for every track in your DJ life.</p></div><div class="heading-actions"><button class="button" data-action="csv">⇧ Import CSV</button><button class="button button-primary" data-action="upload">＋ Add music</button></div></div><div class="toolbar"><div class="search-wrap"><input id="search" value="${esc(query)}" placeholder="Search tracks, artists, tags…" /></div><select id="genreFilter"><option value="all">All genres</option>${unique('genre').map(v=>`<option ${genreFilter===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select><select id="moodFilter"><option value="all">All moods</option>${moods.map(v=>`<option ${moodFilter===v?'selected':''} value="${esc(v)}">${v}</option>`).join('')}</select><button class="button button-small" data-action="dupes">Find duplicates</button></div><div class="card table-card"><div class="table-head"><span>TRACK</span><span>GENRE</span><span>BPM</span><span>KEY</span><span>MOOD</span><span style="text-align:right">ACTIONS</span></div><div id="trackRows"></div></div><div class="notice">Measured: BPM and energy are estimated from audio. Suggested: key, mood, genre and event fit may need your ears and edits. Audio files stay on this device.</div></div>`;}
function unique(k){return [...new Set(tracks.map(t=>t[k]).filter(Boolean))].sort();}
function renderLibraryRows(){const box=$('#trackRows');if(!box)return;let rows=tracks.filter(t=>{const q=query.toLowerCase();return (!q||[t.title,t.artist,t.album,t.genre,t.language,...(t.tags||[])].join(' ').toLowerCase().includes(q))&&(genreFilter==='all'||t.genre===genreFilter)&&(moodFilter==='all'||t.mood===moodFilter);});if(!rows.length){box.innerHTML=`<div class="empty-library"><div class="empty-icon">${tracks.length?'⌕':'♫'}</div><h3>${tracks.length?'No tracks match this view':'Your music library starts here'}</h3><p>${tracks.length?'Try another search or filter.':'Add audio files from your Mac for local analysis, or import a CSV track list to start building sets.'}</p>${tracks.length?'':'<button class="button button-primary" data-action="upload">＋ Add music</button> <button class="button" data-action="csv">Import CSV</button>'}</div>`;return;}box.innerHTML=rows.map(t=>`<div class="track-row"><div class="track-main"><div class="track-cover">♫</div><div style="min-width:0"><div class="track-name">${esc(t.title)}</div><div class="track-artist">${esc(t.artist||'Unknown artist')}${t.album?' · '+esc(t.album):''}</div></div></div><div><span class="genre-tag">${esc(t.genre||'Untagged')}</span></div><div class="mono">${t.bpm?Math.round(t.bpm):'—'}</div><div class="mono">${esc(t.key||'—')}</div><div class="mood-tag">${esc(t.mood||'—')}</div><div class="row-actions"><button title="Track details and edit" data-action="edit-track" data-id="${t.id}">✎</button><button title="Remove track" data-action="delete-track" data-id="${t.id}">×</button></div></div>`).join('');}
function builderView(){let p=playlistById(activePlaylist), items=p?.tracks||[];return `<div class="page"><div class="page-heading"><div><div class="eyebrow">AI DJ SET SEQUENCER</div><h1>${p?esc(p.name):'Build a DJ set'}</h1><p class="page-sub">Shape a night with your own music, then make it yours.</p></div><div class="heading-actions"><button class="button" data-action="view-library">Browse music</button>${p?'<button class="button" data-action="export-csv">⇩ Export set CSV</button>':''}</div></div><div class="playlist-layout"><section class="card builder-card"><div class="eyebrow">01 · SET THE SCENE</div><label for="prompt">What should this set feel like?</label><textarea id="prompt" placeholder="e.g. A 3-hour Bollywood and Punjabi Diwali party. Start familiar and feel-good, build the dance floor, then close with iconic singalongs.">${p?esc(p.prompt||''):''}</textarea><div class="hint">Describe event, genre, duration and energy journey. With YouTube connected, Setlist AI also searches public videos and playlist track lists automatically.</div><div class="form-row"><div><label for="setName">Set name</label><input id="setName" placeholder="e.g. Diwali at home" value="${p?esc(p.name):''}" /></div><div><label for="duration">Duration</label><select id="duration"><option value="60">1 hour</option><option value="90">90 minutes</option><option value="120">2 hours</option><option value="180" selected>3 hours</option><option value="240">4 hours</option></select></div></div><label>Event tags <span style="color:#667281">· optional filter</span></label><div class="event-tags">${events.map(x=>`<label class="event-tag" style="cursor:pointer"><input type="checkbox" value="${esc(x)}" ${p?.events?.includes(x)?'checked':''} style="accent-color:#b9a9ff;vertical-align:middle"> ${esc(x)}</label>`).join('')}</div><div style="margin-top:20px;display:flex;gap:8px"><button class="button button-primary" data-action="generate">✦ ${p?'Regenerate sequence':'Generate my set'}</button>${p?'<button class="button" data-action="save-playlist">Save changes</button>':''}</div>${!tracks.length?'<div class="notice">No local audio yet. The builder will search Apple Music and connected YouTube public playlists from your prompt.</div>':''}</section><div><section class="card" style="padding:0"><div class="playlist-head"><div><h2>${p?'Your sequence':'Your sequence will appear here'}</h2><p>${items.length?`${items.length} tracks · approx. ${prettyDuration(items.reduce((s,x)=>s+(x.duration||210),0))} · drag rows to reorder`: 'A good set has a beginning, a lift, a peak and a memorable landing.'}</p></div><div class="playlist-tools">${p?'<button class="button button-small" data-action="save-playlist">Save</button>':''}</div></div><div class="playlist-tracks" id="playlistRows">${items.length?items.map((it,i)=>playlistRow(it,i)).join(''):`<div class="empty-state"><div class="empty-icon">↗</div>Tracks from your library will line up here.<br><span style="font-size:10px">Catalog picks are arranged around your requested style; audio transition data is shown only when available.</span></div>`}</div></section>${items.length?`<section class="card energy-card" id="energyCard"><div class="card-header" style="margin-bottom:0"><div><div class="card-title">Energy progression</div><div class="card-kicker">Your planned set energy arc · drag a point up or down to adjust</div></div><span class="mono" style="color:var(--lime)">1–10</span></div><div class="energy-chart"><svg class="energy-svg" id="energySvg" viewBox="0 0 600 180" preserveAspectRatio="none"></svg></div><div class="energy-labels"><span>WARM UP</span><span>BUILD</span><span>PEAK</span><span>LAND</span></div></section>`:''}</div></div><div class="notice">Set recommendations are rule-based. These catalogs do not supply reliable BPM, key, or measured energy, so the sequence follows your requested style and planned energy arc. Preview music through your licensed service.</div></div>`;}
function playlistRow(item,i){const t=trackById(item.trackId)||item;return `<div class="playlist-row" draggable="true" data-index="${i}"><span class="drag">⠿</span><span class="playlist-pos">${String(i+1).padStart(2,'0')}</span><span class="small-cover">♫</span><div style="min-width:0"><div class="track-name">${esc(t.title)}</div><div class="track-artist">${esc(t.artist||'Unknown artist')}</div><div class="reason">${esc(item.reason||'Fits the energy arc')}</div>${t.sourceUrl?`<a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="track-artist" style="color:var(--lime)">${esc(t.source||'Source')} ↗</a>`:''}</div><span class="mono">${t.bpm?Math.round(t.bpm)+'':'—'}</span><span class="energy-pill">${item.energyOverride||t.energy||'—'}/10</span><span class="compat">${item.compat==='catalog'?'catalog':`${item.compat||'—'} match`}</span><button class="remove-track" title="Remove from set" data-action="remove-playlist-track" data-id="${activePlaylist}" data-index="${i}">×</button></div>`;}
function settingsView(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">YOUR SETUP</div><h1>Settings & integrations</h1><p class="page-sub">Connect YouTube once for public videos and playlist discovery.</p></div></div><div class="settings-grid"><section class="card"><div class="card-title">Local music library</div><p>Track data, tags and playlists are saved in this browser. After publishing the app, your phone can generate and save its own playlists without the Mac. Mac and phone libraries remain separate unless a shared database is added.</p><div class="feature-chip"><b>${tracks.length} tracks · ${playlists.length} sets</b>${tracks.filter(t=>t.blob).length} imported audio files are stored in this browser.</div></section><section class="card"><div class="card-title">Audio analysis</div><p>BPM and energy are estimated from decoded audio in your browser. Key detection is an approximate chroma profile. Mood and event fit are editable suggestions.</p><div class="feature-chip"><b>Runs on your device</b>Analysis quality varies with audio format, intros and silence.</div></section><section class="card"><div class="card-title">YouTube Data API</div><p>One-time setup: create a Google Cloud project, enable YouTube Data API v3, create an API key, then paste it here. Public search does not require OAuth.</p><label class="field-label" for="youtubeApiKey">YouTube API key</label><input class="form-input" id="youtubeApiKey" type="password" autocomplete="off" placeholder="${youtubeApiKey?'Key saved in this browser':'Paste API key'}" value=""><div style="display:flex;gap:8px;align-items:center;margin-top:10px"><button class="button button-small button-primary" data-action="save-youtube-key">Save key</button><span class="mono">${youtubeApiKey?'CONNECTED':'NOT CONNECTED'}</span></div><div class="feature-chip" style="margin-top:12px"><b>Sent directly to Google</b>Restrict the key to YouTube Data API v3 and your app origin in Google Cloud.</div></section><section class="card"><div class="card-title">Apple Music discovery</div><p>Apple catalog search works in-app without a key. It returns catalog metadata, but not BPM, key or measured energy.</p></section><section class="card"><div class="card-title">DJ software exports</div><p>CSV export gives you a portable track list. Native Serato and Rekordbox library formats need separate, version-aware adapters.</p><button class="button button-small" data-action="export-csv">⇩ Export library CSV</button></section></div><div class="drop-zone"><b>Manage your local data</b><p>Download a copy of your track metadata, or remove the current browser library.</p><button class="button button-small" data-action="export-csv">⇩ Export library CSV</button> <button class="button button-small" data-action="clear-library">Clear library</button></div></div>`;}
function discoverView(){
 const ytLabel=youtubeApiKey?'YouTube connected':'YouTube key needed in Settings';
 const pageSize=24,total=catalogResults.length,pageCount=Math.ceil(total/pageSize),page=Math.min(catalogPage,Math.max(0,pageCount-1));
 const first=page*pageSize,visible=catalogResults.slice(first,first+pageSize),appleCount=catalogResults.filter(t=>t.source==='Apple Music').length,youtubeCount=catalogResults.filter(t=>t.source==='YouTube').length;
 const status=total?`Showing ${first+1}–${Math.min(first+pageSize,total)} of ${total} saved results · Apple ${appleCount} · YouTube ${youtubeCount}`:catalogBusy?'Searching Apple and YouTube…':`${ytLabel}. YouTube setup is one-time; see Settings. Search results stay in this page.`;
 const pager=pageCount>1?`<div class="catalog-pager"><button class="button button-small" data-action="catalog-prev" ${page===0?'disabled':''}>← Previous</button><span>Page ${page+1} of ${pageCount}</span><button class="button button-small" data-action="catalog-next" ${page>=pageCount-1?'disabled':''}>Next →</button></div>`:'';
 const fileWarning=location.protocol==='file:'?'<div class="notice">This copy was opened as a file. YouTube search needs the app served from <b>http://127.0.0.1:8000</b>. Open <b>start.command</b>, then save your YouTube key again in that version; browser storage is separate for each address.</div>':'';
 return `<div class="page"><div class="page-heading"><div><div class="eyebrow">AUTOMATIC MUSIC DISCOVERY</div><h1>Find your next record.</h1><p class="page-sub">Search once across Apple’s catalog and public YouTube videos and playlists. Matches are saved to your library.</p></div></div>${fileWarning}<section class="card discover-search"><div class="card-header"><div><div class="card-title">Search music sources</div><div class="card-kicker">Apple Music · YouTube videos · YouTube playlists</div></div><span class="mono">${youtubeApiKey?'YOUTUBE READY':'APPLE READY'}</span></div><div class="toolbar"><div class="search-wrap"><input id="sourceQuery" value="${esc(catalogSearchText)}" placeholder="Track, artist, genre, event or mood…" /></div><button class="button button-primary" data-action="discover-search">${catalogBusy?'Searching…':'Search sources'}</button></div><div class="genre-picks"><span>QUICK SEARCH</span>${['Holi playlist','Bollywood dance','Punjabi party','Indian pop','Afrobeats','90s hits','Tech house'].map(q=>`<button data-action="discover-genre" data-query="${esc(q)}">${esc(q)}</button>`).join('')}</div><div id="catalogStatus" class="catalog-status">${status}</div>${catalogError?`<div class="notice catalog-error">YouTube/Apple search message: ${esc(catalogError)}</div>`:''}${pager}${visible.length?`<div class="catalog-result-list">${visible.map(t=>`<div class="catalog-result"><div class="catalog-art">${t.artworkUrl?`<img src="${esc(t.artworkUrl)}" alt="" />`:'♫'}</div><div class="catalog-result-info"><b>${esc(t.title)}</b><small>${esc(t.artist)} · ${esc(t.source==='YouTube'?(t.sourcePlaylist||'YouTube video'):(t.album||'Single'))} · ${esc(t.genre||t.source||'')}</small></div><span class="catalog-duration">${prettyDuration(t.duration)}</span><a class="button button-small" href="${esc(t.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t.source==='YouTube'?'YouTube ↗':'Apple ↗'}</a></div>`).join('')}${pager}</div>`:catalogResults.length?'':''}</section><div class="notice">YouTube results can surface public playlist track lists and videos without opening provider tabs. YouTube metadata may have noisy song/artist names and does not include DJ BPM, key or measured energy. Search text goes to Apple and, when connected, Google.</div></div>`;
}
function searchApple(term){return new Promise((resolve,reject)=>{const cb=`setlistApple_${uid().replace(/[^a-z0-9]/gi,'')}`,script=document.createElement('script');let timer;const clean=()=>{delete window[cb];script.remove();clearTimeout(timer);};window[cb]=payload=>{clean();resolve(payload?.results||[]);};script.onerror=()=>{clean();reject(new Error('The music catalog could not be reached. Check your internet connection and try again.'));};script.src=`https://itunes.apple.com/search?term=${encodeURIComponent(term)}&entity=song&country=IN&limit=200&callback=${cb}`;timer=setTimeout(()=>{clean();reject(new Error('The catalog did not respond in time. Try again shortly.'));},15000);document.body.append(script);});}
function saveYoutubeKey(){const value=$('#youtubeApiKey')?.value.trim();if(!value){notify('Paste your YouTube API key first.');return;}youtubeApiKey=value;localStorage.setItem('setlist-youtube-api-key',value);render();notify('YouTube search is connected in this browser.');}
async function youtubeApi(resource,params){if(!youtubeApiKey)throw new Error('Add a YouTube Data API key in Settings to search YouTube.');const url=new URL(`https://www.googleapis.com/youtube/v3/${resource}`);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));const response=await fetch(url,{headers:{'X-Goog-Api-Key':youtubeApiKey}});const payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'YouTube search failed. Check the API key and quota.');return payload;}
function youtubeDuration(iso=''){const m=iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);return m?(+m[1]||0)*3600+(+m[2]||0)*60+(+m[3]||0):0;}
async function searchYoutube(term){if(!youtubeApiKey)return [];const videos=await youtubeApi('search',{part:'snippet',q:term,type:'video',videoEmbeddable:'true',maxResults:15,safeSearch:'none'});let rows=(videos.items||[]).map(x=>({videoId:x.id?.videoId,title:x.snippet?.title||'Unknown title',artist:x.snippet?.channelTitle||'YouTube creator',artworkUrl:x.snippet?.thumbnails?.medium?.url||x.snippet?.thumbnails?.default?.url||'',sourceUrl:`https://www.youtube.com/watch?v=${x.id?.videoId}`,catalogQuery:term,sourcePlaylist:''})).filter(x=>x.videoId);const pl=await youtubeApi('search',{part:'snippet',q:term,type:'playlist',maxResults:4});const playlistMatches=(pl.items||[]).filter(x=>x.id?.playlistId);for(const found of playlistMatches.slice(0,2)){const playlistId=found.id.playlistId,playlistTitle=found.snippet?.title||'YouTube playlist';try{const items=await youtubeApi('playlistItems',{part:'snippet,contentDetails',playlistId,maxResults:25});for(const x of items.items||[]){const s=x.snippet||{},videoId=s.resourceId?.videoId;if(!videoId)continue;rows.push({videoId,title:s.title||'Unknown title',artist:s.videoOwnerChannelTitle||s.channelTitle||'YouTube creator',artworkUrl:s.thumbnails?.medium?.url||s.thumbnails?.default?.url||'',sourceUrl:`https://www.youtube.com/watch?v=${videoId}`,catalogQuery:term,sourcePlaylist:playlistTitle});}}catch(e){console.warn('Could not expand public YouTube playlist',e.message);}}
 const uniqueRows=[...new Map(rows.map(x=>[x.videoId,x])).values()];if(!uniqueRows.length)return [];const details=await youtubeApi('videos',{part:'contentDetails',id:uniqueRows.map(x=>x.videoId).slice(0,50).join(',')});const durations=new Map((details.items||[]).map(x=>[x.id,youtubeDuration(x.contentDetails?.duration)]));return uniqueRows.map(x=>({...x,duration:durations.get(x.videoId)||0}));}
async function saveYoutubeResults(results,searchTerm,eventTags){const saved=[];for(const r of results){if(!r.videoId)continue;const id=`youtube-${r.videoId}`,old=trackById(id);let t=old||{id,title:r.title,artist:r.artist,album:r.sourcePlaylist||'',genre:'',language:'',bpm:0,key:'',energy:0,danceability:0,mood:'',events:[],tags:['catalog','youtube',...(r.sourcePlaylist?['playlist']:[])],source:'YouTube',sourceUrl:r.sourceUrl,youtubeVideoId:r.videoId,artworkUrl:r.artworkUrl||'',duration:r.duration||0,addedAt:Date.now(),analysis:'catalog metadata only'};t.title=r.title||t.title;t.artist=r.artist||t.artist;t.album=r.sourcePlaylist||t.album;t.duration=r.duration||t.duration;t.sourceUrl=r.sourceUrl;t.artworkUrl=r.artworkUrl||t.artworkUrl;t.youtubeVideoId=r.videoId;t.sourcePlaylist=r.sourcePlaylist||t.sourcePlaylist||'';t.catalogQuery=[...new Set([...(t.catalogQuery||'').split(' | ').filter(Boolean),r.catalogQuery||searchTerm])].join(' | ');t.events=[...new Set([...(t.events||[]),...eventTags])];t.tags=[...new Set([...(t.tags||[]),'catalog','youtube',...(r.sourcePlaylist?['playlist']:[])])];await put(STORE,t);if(!tracks.some(x=>x.id===id))tracks.push(t);saved.push(t);}return saved;}
async function searchCatalogFromInput(){const input=$('#sourceQuery'),term=(input?.value||'').trim();if(!term){notify('Enter a song, artist, genre or event to search.');return;}catalogSearchText=term;catalogPage=0;catalogError='';catalogBusy=true;render();const outcomes=await Promise.allSettled([searchApple(term),youtubeApiKey?searchYoutube(term):Promise.resolve([])]);let savedApple=[],savedYoutube=[],errors=[];if(outcomes[0].status==='fulfilled')savedApple=await saveCatalogResults(outcomes[0].value,term,[]);else errors.push(outcomes[0].reason.message);if(outcomes[1].status==='fulfilled')savedYoutube=await saveYoutubeResults(outcomes[1].value,term,[]);else errors.push(outcomes[1].reason.message);catalogResults=mixCatalogSources(savedApple,savedYoutube);catalogError=errors.join(' · ');catalogBusy=false;render();if(errors.length)notify(`${catalogResults.length} saved. ${errors[0]}`);else notify(`Found and saved ${savedApple.length} Apple and ${savedYoutube.length} YouTube matches.`);}
function mixCatalogSources(apple,youtube){const mixed=[];for(let i=0;i<Math.max(apple.length,youtube.length);i++){if(apple[i])mixed.push(apple[i]);if(youtube[i])mixed.push(youtube[i]);}return mixed;}
async function saveCatalogResults(results,searchTerm,eventTags){const byTrack=new Map();for(const r of results.filter(x=>x.kind==='song'&&x.trackId)){const old=byTrack.get(r.trackId),terms=[...(old?.catalogQuery||'').split(' | '),r.catalogQuery||searchTerm].filter(Boolean);byTrack.set(r.trackId,{...r,catalogQuery:[...new Set(terms)].join(' | ')});}const uniqueResults=[...byTrack.values()],saved=[];for(const r of uniqueResults){const id=`apple-${r.trackId}`,catalogQuery=r.catalogQuery||searchTerm;let t=trackById(id);if(!t)t={id,title:r.trackName||'Unknown title',artist:r.artistName||'Unknown artist',album:r.collectionName||'',genre:r.primaryGenreName||'',language:'',bpm:0,key:'',energy:0,danceability:0,mood:'',events:eventTags,tags:['catalog','apple',...catalogQuery.toLowerCase().split(/\W+/).filter(Boolean).slice(0,4)],source:'Apple Music',sourceUrl:r.trackViewUrl||'',artworkUrl:r.artworkUrl100||'',releaseDate:r.releaseDate||'',duration:Math.round((r.trackTimeMillis||0)/1000),addedAt:Date.now(),analysis:'catalog metadata only',catalogQuery};else{t.events=[...new Set([...(t.events||[]),...eventTags])];t.catalogQuery=catalogQuery;}await put(STORE,t);if(!tracks.some(x=>x.id===t.id))tracks.push(t);saved.push(t);}return saved;}
function catalogQueries(prompt){const text=prompt.toLowerCase(),genres=[['Bollywood',['bollywood','hindi','filmi']],['Punjabi',['punjabi','bhangra']],['EDM',['edm','electronic','dance music']],['House',['house','tech house']],['Hip hop',['hip-hop','hip hop','rap']],['Afrobeats',['afrobeat','afrobeats','afro']],['Latin',['latin','reggaeton']],['Pop',['pop']],['Regional Indian',['indian regional','tamil','telugu','marathi','bengali','gujarati']]];const hit=genres.filter(([,words])=>words.some(w=>text.includes(w))).map(([name])=>name);const variants={Bollywood:['Bollywood songs','Hindi dance songs','Bollywood party','Hindi hits'],Punjabi:['Punjabi songs','Punjabi party','Bhangra hits','Punjabi wedding songs'],EDM:['EDM hits','Electronic dance music'],House:['House music','Tech house'], 'Hip hop':['Hip hop party','Rap hits'],Afrobeats:['Afrobeats hits','Afro party'],Latin:['Latin dance hits','Reggaeton'],Pop:['Pop party hits'],'Regional Indian':['Indian regional hits','Tamil Telugu hits']};if(hit.length)return [...new Set(hit.flatMap(g=>variants[g]||[g]))].slice(0,8);const terms=prompt.split(/\s+/).filter(w=>w.length>2&&!['create','make','build','playlist','songs','song','start','with','finish','that','gradually','increase','energy','middle','the','for','and'].includes(w.toLowerCase()));return [terms.slice(0,5).join(' ')||'popular party songs'];}
function youtubePrompt(prompt){const p=prompt.toLowerCase(),event=['holi','diwali','wedding','sangeet','house party','college party','corporate','sundowner'].find(x=>p.includes(x));const genres=['bollywood','hindi','punjabi','bhangra','edm','house','afrobeats','hip-hop','latin','retro'].filter(x=>p.includes(x));return [event,genres.join(' '),'playlist songs'].filter(Boolean).join(' ')||`${prompt.slice(0,90)} playlist`;}
async function findCatalogForSet(prompt,eventTags){const queries=catalogQueries(prompt);const appleTask=Promise.all(queries.map(async q=>(await searchApple(q)).map(r=>({...r,catalogQuery:q})))).then(xs=>xs.flat());const ytTask=youtubeApiKey?searchYoutube(youtubePrompt(prompt)):Promise.resolve([]);const [ap,yout]=await Promise.allSettled([appleTask,ytTask]);const saved=[];if(ap.status==='fulfilled')saved.push(...await saveCatalogResults(ap.value,prompt,eventTags));if(yout.status==='fulfilled')saved.push(...await saveYoutubeResults(yout.value,prompt,eventTags));if(!saved.length){const err=ap.status==='rejected'?ap.reason:yout.status==='rejected'?yout.reason:null;if(err)throw err;}return saved;}
function soonView(v){const d=['Mood & genre explorer','Explore your collection by feeling, sound and scene.'];return `<div class="page"><div class="page-heading"><div><div class="eyebrow">COMING NEXT</div><h1>${d[0]}</h1><p class="page-sub">${d[1]}</p></div></div><div class="soon-page"><div class="cover">◉</div><h2>Make discovery feel like crate digging.</h2><p>Use the Discover page to search music sources and add track metadata to your library.</p><button class="button" data-view="discover">Open music discovery</button></div></div>`;}
function playlistById(id){return playlists.find(p=>p.id===id)}function trackById(id){return tracks.find(t=>t.id===id)}
async function importAudio(files){if(!files.length)return;notify(`Adding ${files.length} ${files.length===1?'track':'tracks'}…`);for(let i=0;i<files.length;i++){const f=files[i],base=f.name.replace(/\.[^.]+$/,'');if(tracks.some(t=>t.fileName===f.name&&t.fileSize===f.size)){continue;}const parsed=parseFilename(base),track={id:uid(),title:parsed.title,artist:parsed.artist,album:'',fileName:f.name,fileSize:f.size,duration:0,bpm:0,key:'',energy:0,danceability:0,genre:guessGenre(base),language:'',mood:'',events:[],tags:[],addedAt:Date.now(),analysis:'pending',blob:f};tracks.push(track);await put(STORE,track);render();analyseTrack(track).then(async result=>{Object.assign(track,result,{analysis:'estimated'});await put(STORE,track);tracks=[...tracks];render();});}render();notify('Music added. Audio estimates are running in this browser.');}
function parseFilename(s){const p=s.split(/\s[-–—]\s/);return p.length>1?{artist:p[0].trim(),title:p.slice(1).join(' - ').trim()}:{artist:'',title:s.trim()};}
function guessGenre(s){const x=s.toLowerCase();if(/punjabi|bhangra/.test(x))return'Punjabi';if(/bollywood|hindi|filmi/.test(x))return'Bollywood';if(/house|techno|edm|dance/.test(x))return'EDM';if(/hip.?hop|rap/.test(x))return'Hip-hop';if(/afro/.test(x))return'Afrobeat';return '';}
async function analyseTrack(t){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)throw 0;const ctx=new C(),buf=await ctx.decodeAudioData(await t.blob.arrayBuffer());const sr=buf.sampleRate,ch=buf.numberOfChannels,len=Math.min(buf.length,sr*70),data=new Float32Array(len);for(let c=0;c<ch;c++){const d=buf.getChannelData(c);for(let i=0;i<len;i++)data[i]+=d[i]/ch;}const hop=512,env=[];let sum=0;for(let i=0;i<data.length;i+=hop){let v=0;for(let j=i;j<Math.min(i+hop,data.length);j++)v+=data[j]*data[j];env.push(Math.sqrt(v/Math.max(1,Math.min(hop,data.length-i))));}const smooth=env.map((v,i)=>v-(env[Math.max(0,i-1)]+env[Math.max(0,i-2)]+env[Math.max(0,i-3)])/3);let bestLag=0,best=-1;for(let lag=Math.floor(sr/hop*60/180);lag<=Math.ceil(sr/hop*60/65);lag++){let c=0;for(let i=lag;i<smooth.length;i++)c+=smooth[i]*smooth[i-lag];if(c>best){best=c;bestLag=lag;}}let bpm=bestLag?60*sr/(hop*bestLag):0;if(bpm&&bpm<85)bpm*=2;if(bpm>175)bpm/=2;
 const rms=Math.sqrt(data.reduce((s,x)=>s+x*x,0)/Math.max(1,data.length));let flux=0;for(let i=1;i<env.length;i++)flux+=Math.max(0,env[i]-env[i-1]);const energy=Math.max(1,Math.min(10,Math.round(2+rms*23+flux/env.length*95)));const danceability=Math.max(1,Math.min(10,Math.round(3+(bpm>90&&bpm<145?3:1)+energy*.35)));const key=estimateKey(data,sr);await ctx.close();return{duration:buf.duration,bpm:Math.round(bpm),energy,danceability,key,mood:energy>8?'High-energy':energy>6?'Celebratory':energy<4?'Chill':'Feel-good'};}catch{return{analysis:'unavailable',duration:t.duration||0};}}
function estimateKey(data,sr){const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'],chroma=Array(12).fill(0);const size=8192,step=4096;for(let start=0;start+size<data.length;start+=step){for(let k=0;k<12;k++){const freq=440*Math.pow(2,(k-9)/12);const bin=Math.round(freq*size/sr);let re=0,im=0;for(let n=0;n<size;n+=4){const a=2*Math.PI*bin*n/size,v=data[start+n]*(.5-.5*Math.cos(2*Math.PI*n/size));re+=v*Math.cos(a);im-=v*Math.sin(a);}chroma[k]+=Math.hypot(re,im);}}let idx=chroma.indexOf(Math.max(...chroma));return `${names[idx]}?`;}
async function importCSV(file){if(!file)return;try{const text=await file.text(),rows=parseCSV(text);if(rows.length<2)throw Error('The CSV needs a header and at least one track.');const headers=rows[0].map(x=>x.trim().toLowerCase());const col=(row,names)=>{const i=headers.findIndex(h=>names.includes(h));return i<0?'':row[i]||'';};let added=0;for(const row of rows.slice(1)){const title=col(row,['title','track','track name','name']);if(!title)continue;const track={id:uid(),title,artist:col(row,['artist','artists']),album:col(row,['album']),genre:col(row,['genre']),language:col(row,['language']),bpm:Number(col(row,['bpm','tempo']))||0,key:col(row,['key','musical key']),energy:Number(col(row,['energy']))||0,danceability:Number(col(row,['danceability']))||0,mood:col(row,['mood']),events:col(row,['event','events']).split(/[;,|]/).map(x=>x.trim()).filter(Boolean),tags:col(row,['tags','tag']).split(/[;,|]/).map(x=>x.trim()).filter(Boolean),duration:Number(col(row,['duration','duration_seconds']))||0,addedAt:Date.now(),analysis:'imported'};tracks.push(track);await put(STORE,track);added++;}render();notify(`Imported ${added} tracks from CSV.`);}catch(e){notify(`CSV import failed: ${e.message}`);}$('#csvInput').value='';}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(q&&c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
function generatePlaylist(catalogChecked=false){const draftPrompt=$('#prompt')?.value.trim(),draftMinutes=Number($('#duration')?.value)||180,draftEvents=$$('#viewRoot input[type=checkbox]:checked').map(x=>x.value),previous=playlistById(activePlaylist),previousSeconds=previous?.tracks?.reduce((s,it)=>s+((trackById(it.trackId)?.duration)||210),0)||0,isShortCatalogSet=previous?.tracks?.length&&previous.tracks.every(it=>['Apple Music','YouTube'].includes(trackById(it.trackId)?.source))&&previousSeconds<draftMinutes*60*.9,needsCatalog=!tracks.length||(!activePlaylist&&tracks.some(t=>['Apple Music','YouTube'].includes(t.source)))||isShortCatalogSet;if(!draftPrompt){notify('Describe the event or music style first.');return;}if(!catalogChecked&&needsCatalog){notify(youtubeApiKey?'Searching Apple Music and YouTube for your set…':'Searching Apple Music for your set…');findCatalogForSet(draftPrompt,draftEvents).then(found=>{if(!found.length){notify('No catalog tracks matched. Try a genre or artist in your prompt.');return;}catalogResults=found;catalogPage=0;generatePlaylist(true);}).catch(e=>notify(e.message));return;}if(!tracks.length){notify('No catalog tracks matched. Try a broader prompt.');return;}const prompt=draftPrompt,name=$('#setName').value.trim()||nameFromPrompt(prompt)||'Untitled DJ set',minutes=draftMinutes,selectedEvents=draftEvents,words=prompt.toLowerCase();let pool=tracks.slice();const genreHints=[['bollywood',['bollywood','hindi','filmi']],['punjabi',['punjabi','bhangra']],['edm',['edm','electronic']],['house',['house','tech house']],['hip-hop',['hip-hop','hip hop','rap']],['afrobeat',['afrobeat','afro']]];const requested=genreHints.filter(([g,terms])=>terms.some(x=>words.includes(x))).map(([g])=>g);if(requested.length){const matched=pool.filter(t=>{const facts=`${t.genre||''} ${t.title||''} ${t.catalogQuery||''} ${t.sourcePlaylist||''} ${(t.tags||[]).join(' ')}`;const f=facts.toLowerCase();return requested.some(g=>f.includes(g)||(g==="bollywood"&&f.includes("hindi"))||(g==="punjabi"&&f.includes("bhangra")));});if(matched.length)pool=matched;}if(selectedEvents.length){const matched=pool.filter(t=>(t.events||[]).some(e=>selectedEvents.includes(e)));if(matched.length)pool=matched;}
 const avoid=words.includes('familiar')||words.includes('singalong')||words.includes('iconic');pool.sort((a,b)=>{const av=Number(a.energy)||energyDefault(a),bv=Number(b.energy)||energyDefault(b);return av-bv;});const selected=[];let selectedSeconds=0;for(const t of pool){if(selected.length&&selectedSeconds>=minutes*60)break;selected.push(t);selectedSeconds+=t.duration||210;}const low=words.includes('chill')||words.includes('sundowner'),high=words.includes('high-energy')||words.includes('dance floor')||words.includes('peak');const targetCurve=selected.map((_,i)=>{let x=i/Math.max(1,selected.length-1);if(low)return Math.round(3+2*Math.sin(x*Math.PI));if(high)return Math.round(x<.2?3+x*15:x<.72?6+(x-.2)*5:8-(x-.72)*8);return Math.round(3+6*(x<.7?x/.7:1-(x-.7)/.3));});
 // Sort against a deliberately smooth arc, balancing energy, BPM, key and artist repetition.
 let remaining=selected.slice(),ordered=[],last=null;for(let i=0;i<selected.length;i++){const desired=targetCurve[i];remaining.sort((a,b)=>transitionScore(b,last,desired)-transitionScore(a,last,desired));let ix=0;if(last&&avoid){const fresh=remaining.findIndex(t=>(t.artist||'').toLowerCase()!==(last.artist||'').toLowerCase());if(fresh>=0)ix=fresh;}const next=remaining.splice(ix,1)[0];let reason=i===0?'A welcoming opener to establish the room.':reasonFor(next,last,desired),hasData=last&&(last.bpm&&next.bpm||last.key&&next.key||last.energy&&next.energy);ordered.push({trackId:next.id,reason,compat:last?(hasData?`${Math.round(transitionScore(next,last,desired)*100)}%`:'catalog'):'—',energyOverride:desired});last=next;}
 const existing=activePlaylist&&playlistById(activePlaylist);const p={id:activePlaylist||uid(),name,prompt,events:selectedEvents,tracks:ordered,createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()};activePlaylist=p.id;const ix=playlists.findIndex(x=>x.id===p.id);if(ix>=0)playlists[ix]=p;else playlists.unshift(p);put(PLAYLISTS,p).then(()=>{activeView='builder';render();notify(`Built a ${ordered.length}-track set from your library.`);});}
function energyDefault(t){return t.energy|| (t.bpm?Math.max(2,Math.min(9,Math.round((t.bpm-70)/13))):5)}
function transitionScore(t,last,desired){let score=1-Math.abs(energyDefault(t)-desired)/10;if(last){const bpmA=Number(last.bpm)||120,bpmB=Number(t.bpm)||120,ratio=Math.min(bpmA,bpmB)/Math.max(bpmA,bpmB);score+=ratio*.2;score+=last.key&&t.key&&last.key[0]===t.key[0]?.1:0;score+=last.genre&&last.genre===t.genre?.08:0;if(last.artist&&last.artist===t.artist)score-=.12;}return Math.max(0,Math.min(1,score));}
function reasonFor(t,last,desired){const parts=[];if(last?.bpm&&t.bpm)parts.push(Math.abs(t.bpm-last.bpm)<8?'close tempo feel':Math.abs(t.bpm-last.bpm)<18?'manageable tempo shift':'fresh tempo change');if(last?.key&&t.key&&last.key[0]===t.key[0])parts.push('shared key center');if(last?.genre&&last.genre===t.genre)parts.push('keeps the genre thread');parts.push(`energy ${desired}/10 shapes the ${desired>7?'peak':desired<5?'warm-up':'build'}`);return parts.slice(0,2).join(' · ')+'.';}
function nameFromPrompt(p){const m=p.match(/(?:for|at) (?:a |an )?([\w '-]+?)(?: party| night| set| event|\.|$)/i);return m?m[1].trim().replace(/\b\w/g,x=>x.toUpperCase())+' set':'';}
function savePlaylist(){const p=playlistById(activePlaylist);if(!p)return;const name=$('#setName')?.value.trim();if(name)p.name=name;p.prompt=$('#prompt')?.value||p.prompt;p.events=$$('#viewRoot input[type=checkbox]:checked').map(x=>x.value);p.updatedAt=Date.now();put(PLAYLISTS,p).then(()=>{playlists=[...playlists];render();notify('Set saved on this device.');});}
function removePlaylistTrack(id,index){const p=playlistById(id);if(!p)return;p.tracks.splice(index,1);p.updatedAt=Date.now();put(PLAYLISTS,p).then(()=>{render();notify('Track removed from the set.');});}
function deletePlaylist(id){const p=playlistById(id);if(!p)return;remove(PLAYLISTS,id).then(()=>{playlists=playlists.filter(x=>x.id!==id);activeView='dashboard';activePlaylist=null;render();notify('Set deleted.');});}
function drawEnergyChart(){const svg=$('#energySvg'),p=playlistById(activePlaylist);if(!svg||!p)return;const n=p.tracks.length,pts=p.tracks.map((x,i)=>`${n===1?300:20+i*560/(n-1)},${170-(x.energyOverride||energyDefault(trackById(x.trackId)||{}))*15}`).join(' ');svg.innerHTML=`<defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c9f36a" stop-opacity=".22"/><stop offset="1" stop-color="#c9f36a" stop-opacity="0"/></linearGradient></defs><polygon points="20,180 ${pts} 580,180" fill="url(#fill)"/><polyline points="${pts}" fill="none" stroke="#c9f36a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${p.tracks.map((x,i)=>{const cx=n===1?300:20+i*560/(n-1),cy=170-(x.energyOverride||energyDefault(trackById(x.trackId)||{}))*15;return `<circle cx="${cx}" cy="${cy}" r="5" fill="#c9f36a" stroke="#141922" stroke-width="2" data-energy-index="${i}"/>`;}).join('')}`;svg.onpointerdown=e=>{const point=e.target.closest('[data-energy-index]');if(!point)return;const idx=Number(point.dataset.energyIndex);svg.setPointerCapture(e.pointerId);const move=ev=>{const r=svg.getBoundingClientRect(),y=(ev.clientY-r.top)/r.height*180;const val=Math.max(1,Math.min(10,Math.round((170-y)/15)));p.tracks[idx].energyOverride=val;drawEnergyChart();};const end=()=>{svg.removeEventListener('pointermove',move);svg.removeEventListener('pointerup',end);put(PLAYLISTS,p);};svg.addEventListener('pointermove',move);svg.addEventListener('pointerup',end);};
 const rows=$$('#playlistRows .playlist-row');rows.forEach(el=>{el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.index);};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain')),to=Number(el.dataset.index);if(from===to)return;const moved=p.tracks.splice(from,1)[0];p.tracks.splice(to,0,moved);p.updatedAt=Date.now();put(PLAYLISTS,p).then(()=>render());};});}
function editTrack(id){const t=trackById(id);if(!t)return;const body=$('#trackDialogBody');body.innerHTML=`<div class="eyebrow">TRACK DETAILS · EDITABLE</div><h2>${esc(t.title)}</h2><p>Audio facts are estimates. Labels and metadata can be corrected to fit your library.</p>${t.sourceUrl?`<p>Found on ${esc(t.source||'music service')} · <a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener noreferrer" style="color:var(--lime)">Open source search ↗</a></p>`:''}<div class="track-detail-grid"><div class="detail-box"><small>Estimated BPM</small><b>${t.bpm?Math.round(t.bpm):'Not analyzed'}</b></div><div class="detail-box"><small>Estimated key</small><b>${esc(t.key||'Not analyzed')}</b></div><div class="detail-box"><small>Energy / danceability</small><b>${t.energy||'—'} / ${t.danceability||'—'}</b></div><div class="detail-box"><small>Duration</small><b>${prettyDuration(t.duration)}</b></div></div><label class="field-label">Title</label><input class="form-input" id="editTitle" value="${esc(t.title)}"><label class="field-label">Artist</label><input class="form-input" id="editArtist" value="${esc(t.artist||'')}"><label class="field-label">Album</label><input class="form-input" id="editAlbum" value="${esc(t.album||'')}"><div class="form-row"><div><label class="field-label">Genre</label><input class="form-input" id="editGenre" value="${esc(t.genre||'')}"></div><div><label class="field-label">Language</label><input class="form-input" id="editLanguage" value="${esc(t.language||'')}"></div></div><div class="form-row"><div><label class="field-label">Mood</label><select class="form-input" id="editMood"><option value="">Choose mood</option>${moods.map(m=>`<option ${t.mood===m?'selected':''}>${m}</option>`).join('')}</select></div><div><label class="field-label">Events (comma separated)</label><input class="form-input" id="editEvents" value="${esc((t.events||[]).join(', '))}"></div></div><label class="field-label">Custom tags (comma separated)</label><input class="form-input" id="editTags" value="${esc((t.tags||[]).join(', '))}"><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px"><button class="button" onclick="document.querySelector('#trackDialog').close()">Cancel</button><button class="button button-primary" id="saveTrack">Save track</button></div>`;body.querySelector('#saveTrack').onclick=async()=>{for(const [k,s] of Object.entries({title:'#editTitle',artist:'#editArtist',album:'#editAlbum',genre:'#editGenre',language:'#editLanguage',mood:'#editMood'}))t[k]=body.querySelector(s).value.trim();t.events=body.querySelector('#editEvents').value.split(',').map(x=>x.trim()).filter(Boolean);t.tags=body.querySelector('#editTags').value.split(',').map(x=>x.trim()).filter(Boolean);await put(STORE,t);tracks=[...tracks];$('#trackDialog').close();render();notify('Track details saved.');};$('#trackDialog').showModal();}
function deleteTrack(id){const t=trackById(id);if(!t)return;if(!confirm(`Remove “${t.title}” from this library?`))return;remove(STORE,id).then(()=>{tracks=tracks.filter(x=>x.id!==id);render();notify('Track removed from your library.');});}
function showDuplicates(){const seen=new Map(),dupes=[];for(const t of tracks){const k=`${t.title}|${t.artist}`.toLowerCase();if(seen.has(k))dupes.push(t);else seen.set(k,t);}notify(dupes.length?`${dupes.length} likely duplicate${dupes.length===1?'':'s'} found. Search the library to review.`:'No likely duplicates found.');if(dupes.length){query='';genreFilter='all';moodFilter='all';render();}}
function reanalyzeMissing(){const todo=tracks.filter(t=>t.blob&&!t.bpm);if(!todo.length){notify('No imported audio files need analysis.');return;}todo.forEach(t=>analyseTrack(t).then(async x=>{Object.assign(t,x,{analysis:'estimated'});await put(STORE,t);tracks=[...tracks];render();}));notify(`Analyzing ${todo.length} tracks locally…`);}
function clearLibrary(){if(!confirm('Clear all tracks and sets stored in this browser? This cannot be undone.'))return;const tx=db.transaction([STORE,PLAYLISTS],'readwrite');tx.objectStore(STORE).clear();tx.objectStore(PLAYLISTS).clear();tx.oncomplete=()=>{tracks=[];playlists=[];activePlaylist=null;activeView='dashboard';render();notify('Local library cleared.');};}
function exportCSV(){const rows=[['title','artist','album','genre','language','bpm','key','energy','danceability','mood','events','tags','duration']];for(const t of tracks){rows.push([t.title,t.artist,t.album,t.genre,t.language,t.bpm,t.key,t.energy,t.danceability,t.mood,(t.events||[]).join(';'),(t.tags||[]).join(';'),t.duration]);}if(activePlaylist){const p=playlistById(activePlaylist);rows.splice(1,rows.length-1,...p.tracks.map((it,i)=>{const t=trackById(it.trackId)||{};return [String(i+1).padStart(2,'0')+' '+(t.title||''),t.artist,t.album,t.genre,t.language,t.bpm,t.key,it.energyOverride||t.energy,t.danceability,t.mood,(t.events||[]).join(';'),(t.tags||[]).join(';'),t.duration];}));}const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=(activePlaylist?(playlistById(activePlaylist)?.name||'set'):'setlist-library').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.csv';a.click();URL.revokeObjectURL(url);notify('CSV export downloaded.');}
document.addEventListener('DOMContentLoaded',init);
